export default {
  schema: './src/schema.ts',
  out: './drizzle',
  dialect: 'postgresql',
  dbCredentials: {
    // Migrations are authored as reviewed .sql files, not generated by Drizzle.
    // Drizzle is used for typed, non-spatial CRUD only (spec 6). This config
    // exists so `drizzle-kit generate` can be run for auxiliary helpers if a
    // future change needs it; it is not part of the migration path.
    url: process.env.DATABASE_MIGRATOR_URL ?? process.env.DATABASE_URL ?? '',
  },
}